def decode_bundle():
    raw=base64.b64decode(BUNDLE)
    if hashlib.sha256(raw).hexdigest()!=BUNDLE_SHA256:
        raise ValueError('Update file is damaged. Download it again.')
    with zipfile.ZipFile(io.BytesIO(raw)) as archive:
        if archive.testzip() is not None:
            raise ValueError('Update archive is damaged')
        manifest=json.loads(archive.read('__manifest__.json').decode('utf-8'))
        files={name:archive.read(name) for name in manifest['files']}
    for name,data in files.items():
        path=Path(name)
        if path.is_absolute() or '..' in path.parts or name=='.env' or name.startswith('frontend/'):
            raise ValueError('Forbidden update target')
        if hashlib.sha256(data).hexdigest()!=manifest['files'][name]:
            raise ValueError('File checksum mismatch: '+name)
    return manifest,files

def install(project,check_only=False):
    project=Path(project).resolve()
    if not (project/'app.py').is_file() or not (project/'embedder.py').is_file():
        raise ValueError('Save this file beside app.py in your Scheme-Saathi folder, or pass --project PATH.')
    manifest,files=decode_bundle()
    index_manifest=json.loads(files['index/manifest.json'].decode('utf-8'))
    if index_manifest['model']!=manifest['model']:
        raise ValueError('Wrong embedding model in update')
    for name in files:
        if not (project/name).resolve().is_relative_to(project):
            raise ValueError('Update target escapes the project folder')
    # Merge the ignore rule; preserve any user additions to .gitignore.
    ignore=project/'.gitignore'
    old_ignore=ignore.read_text(encoding='utf-8') if ignore.exists() else ''
    rule='/.scheme-saathi-backups/'
    if rule not in old_ignore.splitlines():
        files['.gitignore']=(old_ignore.rstrip()+'\n'+rule+'\n').encode('utf-8')
    if check_only:
        return {'checked':True,'files':len(files),'chunks':index_manifest['chunks']}
    backup_parent=project/'.scheme-saathi-backups'
    backup_parent.mkdir(exist_ok=True)
    backup=Path(tempfile.mkdtemp(prefix='bca-update-',dir=backup_parent))
    existing=set()
    # Stage complete backups before replacing any project file.
    for name in files:
        dest=project/name
        if dest.exists():
            if not dest.is_file():
                raise ValueError('Update target is not a file: '+name)
            saved=backup/name
            saved.parent.mkdir(parents=True,exist_ok=True)
            shutil.copy2(dest,saved)
            existing.add(name)
    completed=[]
    try:
        for name,data in files.items():
            dest=project/name
            dest.parent.mkdir(parents=True,exist_ok=True)
            with tempfile.NamedTemporaryFile(prefix='saathi-update-',dir=dest.parent,delete=False) as stream:
                staged=Path(stream.name)
                stream.write(data)
            try:
                os.replace(staged,dest)
            finally:
                staged.unlink(missing_ok=True)
            completed.append(name)
    except Exception:
        for name in reversed(completed):
            dest=project/name
            if name in existing:
                shutil.copy2(backup/name,dest)
            else:
                dest.unlink(missing_ok=True)
        raise
    return {'installed':True,'files':len(files),'chunks':index_manifest['chunks'],'backup':str(backup)}

def main():
    parser=argparse.ArgumentParser(description='Install reviewed official BCA scholarship evidence and rebuilt index.')
    parser.add_argument('--project',default=str(Path(__file__).resolve().parent))
    parser.add_argument('--check',action='store_true',help='Verify without changing files')
    args=parser.parse_args()
    print('Scheme Saathi BCA data update')
    print('Stop the Flask server before applying this update.')
    try:
        result=install(args.project,args.check)
    except Exception as error:
        print('UPDATE FAILED:',error)
        return 1
    print(json.dumps(result,indent=2))
    if not args.check:
        print('DONE. Your .env/API key and frontend files were preserved.')
        print('Published guidelines are not confirmation of current application dates or individual eligibility.')
        print(r'Start: .venv\Scripts\python.exe -X utf8 app.py')
        print('Open http://127.0.0.1:7860 and start a NEW conversation.')
    return 0

if __name__=='__main__':
    raise SystemExit(main())
